from pathlib import Path
import numpy as np,json,subprocess
p=Path(__file__).resolve().parent;f=p/'source/HoliznaCC0-Dreams.mp3';sr=12000
x=np.frombuffer(subprocess.check_output(['/opt/homebrew/bin/ffmpeg','-v','error','-i',str(f),'-ac','1','-ar',str(sr),'-f','f32le','pipe:1']),dtype='<f4');hop=120;size=512
frames=np.lib.stride_tricks.sliding_window_view(x,size)[::hop];spec=np.abs(np.fft.rfft(frames*np.hanning(size),axis=1));flux=np.maximum(0,np.diff(np.log1p(10*spec),axis=0)).sum(axis=1);flux=np.r_[0,flux];flux-=np.mean(flux);energies=[float(np.sqrt(np.mean(x[i*sr:min((i+1)*sr,len(x))].astype(float)**2)))for i in range(len(x)//sr)];acf=np.array([np.dot(flux[:-lag],flux[lag:])for lag in range(30,101)]);tops=np.argsort(acf)[-8:][::-1]+30;tempo=[{'BPM':round(6000/int(l),3),'lag':int(l),'score':float(acf[l-30]/acf.max())}for l in tops];best=int(tops[0]);period=best*hop/sr;phase=np.array([np.mean(flux[k::best])for k in range(best)]);offset=int(phase.argmax())*hop/sr
