beats=np.arange(offset,len(x)/sr,period);res={'durationDecoded':len(x)/sr,'workingAnalysisRate':sr,'method':'FFT positive spectral flux + autocorrelation; no installed ML/network service','tentativeTempoCandidates':tempo,'selectedPulseBPM':60/period,'beatOffsetSeconds':offset,'tentative4BeatBarSeconds':4*period,'barPhase':'UNVERIFIED without listening; pulse is a signal estimate only','oneSecondRMS':energies,'candidateBeats':beats.tolist(),'listening':'NOT RUN — no audio audition/perception capability available to this agent','voiceStatus':'VOICE_CONTENT_REQUIRES_DIRECTOR_LISTENING; creator categorizes collection Instrumental'};(p/'SOURCE-MUSICAL-ANALYSIS.json').write_text(json.dumps(res,indent=2));print(json.dumps({k:v for k,v in res.items()if k not in ['oneSecondRMS','candidateBeats']},indent=2))
